parameters.jsCode:
// Formatear remates de PDF para InsForge con hash inmutable
const parsed = $json.output || $json;
const list = Array.isArray(parsed.remates) ? parsed.remates : [];
const validItems = [];

for (const item of list) {
  const price = Number(item.price_amount);
  if (!item.title || isNaN(price) || price <= 0) continue;

  const sourceId = (item.court_or_bank || 'remate-bancario-pdf').toLowerCase().replace(/[^a-z0-9]+/g, '-');
  const folio = item.specs?.finca_folio || item.title.trim();

  // Hash inmutable basado en el folio/título y fuente
  const hashSeed = sourceId + '::' + folio;
  let hash = 0;
  for (let i = 0; i < hashSeed.length; i++) {
    hash = ((hash << 5) - hash) + hashSeed.charCodeAt(i);
    hash |= 0;
  }
  const assetId = 'pdf_' + Math.abs(hash).toString(16);

  const loc = item.location || {};
  const province = loc.province || 'Panamá';
  const corregimiento = loc.corregimiento || 'Bella Vista';
  const district = loc.district || (province === 'Panamá' ? 'Panamá' : corregimiento);

  validItems.push({
    asset_id: assetId,
    vertical: item.vertical === 'vehicles' ? 'vehicles' : 'real_estate',
    title: String(item.title).trim(),
    price_amount: price,
    currency: 'USD',
    location: {
      province: province,
      district: district,
      corregimiento: corregimiento
    },
    raw_data: {
      specs: item.specs || {},
      description: item.description || 'Remate extraído de documento PDF.',
      contact_phone: item.contact_phone || '+507 500-0000',
      source_pdf: true,
      extracted_by: 'llamaparse_groq',
      extracted_at: new Date().toISOString()
    },
    source_id: sourceId,
    source_listing_url: '',
    status: 'active',
    updated_at: new Date().toISOString()
  });
}

return validItems.map(obj => ({ json: obj }));

